// Language-arts practice bank for grade 6.
// KS.bank.ela: multiple choice (roots, context clues, figurative language, conventions).
// KS.bank.spelling: weekly spelling patterns. KS.bank.writing: writing prompts.
window.KS = window.KS || {}; KS.bank = KS.bank || {};
KS.bank.ela = [
  // roots: Greek roots
  { id: 'root-001', skill: 'roots', sub: 'Greek roots', q: 'The root "hydro" in "hydrant" means...', choices: ['fire', 'light', 'water', 'air'], answer: 2, explain: '"Hydro" means water: a hydrant gives firefighters water.' },
  { id: 'root-002', skill: 'roots', sub: 'Greek roots', q: 'The root "bio" in "biology" means...', choices: ['life', 'earth', 'water', 'time'], answer: 0, explain: '"Bio" means life, so biology is the study of living things.' },
  { id: 'root-003', skill: 'roots', sub: 'Greek roots', q: 'The root "photo" in "photograph" means...', choices: ['sound', 'light', 'heat', 'far'], answer: 1, explain: '"Photo" means light. A camera uses light to make a photograph.' },
  { id: 'root-004', skill: 'roots', sub: 'Greek roots', q: 'The root "atmo" in "atmosphere" means...', choices: ['stone', 'heat', 'time', 'vapor or gas'], answer: 3, explain: '"Atmo" comes from the Greek word for vapor. The atmosphere is the layer of gases around Earth.' },
  { id: 'root-005', skill: 'roots', sub: 'Greek roots', q: 'The root "graph" in "autograph" means...', choices: ['self', 'write', 'far', 'measure'], answer: 1, explain: '"Graph" means write. An autograph is your name written by yourself ("auto" means self).' },
  { id: 'root-006', skill: 'roots', sub: 'Greek roots', q: 'The root "tele" in "telescope" means...', choices: ['small', 'light', 'star', 'far'], answer: 3, explain: '"Tele" means far. A telescope helps you see things that are far away.' },
  { id: 'root-007', skill: 'roots', sub: 'Greek roots', q: 'The root "micro" in "microscope" means...', choices: ['large', 'round', 'small', 'bright'], answer: 2, explain: '"Micro" means small. A microscope helps you see very small things.' },
  { id: 'root-008', skill: 'roots', sub: 'Greek roots', q: 'The root "geo" in "geography" means...', choices: ['earth', 'water', 'life', 'heat'], answer: 0, explain: '"Geo" means earth. Geography is the study of Earth\'s lands and places.' },
  { id: 'root-009', skill: 'roots', sub: 'Greek roots', q: 'The root "therm" in "thermometer" means...', choices: ['heat', 'time', 'sound', 'measure'], answer: 0, explain: '"Therm" means heat. A thermometer measures how hot or cold something is ("meter" is the part that means measure).' },
  { id: 'root-010', skill: 'roots', sub: 'Greek roots', q: 'The root "chron" in "synchronize" means...', choices: ['together', 'swim', 'time', 'same'], answer: 2, explain: '"Chron" means time. When you synchronize watches, you make them show the same time ("syn" is the part that means together).' },
  { id: 'root-011', skill: 'roots', sub: 'Greek roots', q: 'The root "phon" in "symphony" means...', choices: ['light', 'sound', 'write', 'heat'], answer: 1, explain: '"Phon" means sound. A symphony is a long piece of music full of sound.' },
  { id: 'root-012', skill: 'roots', sub: 'Greek roots', q: 'The root "auto" in "automatic" means...', choices: ['car', 'fast', 'many', 'self'], answer: 3, explain: '"Auto" means self. An automatic door opens by itself.' },
  { id: 'root-013', skill: 'roots', sub: 'Greek roots', q: 'The root "meter" in "speedometer" means...', choices: ['speed', 'measure', 'sound', 'far'], answer: 1, explain: '"Meter" means measure. A speedometer measures how fast a car is going.' },
  { id: 'root-014', skill: 'roots', sub: 'Greek roots', q: 'The root "logy" in "geology" means...', choices: ['fear of', 'love of', 'study of', 'place for'], answer: 2, explain: '"-logy" means the study of. Geology is the study of the earth and its rocks.' },
  { id: 'root-015', skill: 'roots', sub: 'Greek roots', q: 'The root "astro" in "astronaut" means...', choices: ['star', 'sailor', 'rocket', 'moon'], answer: 0, explain: '"Astro" means star. "Astronaut" means "star sailor" ("naut" is the part that means sailor).' },
  { id: 'root-016', skill: 'roots', sub: 'Greek roots', q: 'Which word contains a root that means "water"?', choices: ['thermal', 'biography', 'telephone', 'dehydrated'], answer: 3, explain: '"Hydro" means water. When you are dehydrated, your body needs more water.' },
  { id: 'root-017', skill: 'roots', sub: 'Greek roots', q: 'Which word contains a root that means "time"?', choices: ['chronicle', 'photograph', 'microphone', 'geology'], answer: 0, explain: '"Chron" means time. A chronicle tells events in the order they happened over time.' },
  { id: 'root-018', skill: 'roots', sub: 'Greek roots', q: 'Which word contains a root that means "light"?', choices: ['hydroplane', 'chronic', 'autograph', 'photosynthesis'], answer: 3, explain: '"Photo" means light. In photosynthesis, plants use light to make food.' },
  { id: 'root-019', skill: 'roots', sub: 'Greek roots', q: 'Which word contains a root that means "far"?', choices: ['microbe', 'thermos', 'television', 'phonics'], answer: 2, explain: '"Tele" means far. A television shows pictures sent from far away.' },
  { id: 'root-020', skill: 'roots', sub: 'Greek roots', q: '"Mom packed my soup in a thermos so it would stay hot until lunch." Using the root "therm," what is a "thermos"?', choices: ['a container that measures time', 'a container that keeps heat in', 'a bag that keeps food dry', 'a bowl that cools soup fast'], answer: 1, explain: '"Therm" means heat, and a thermos keeps hot food hot.' },
  { id: 'root-021', skill: 'roots', sub: 'Greek roots', q: '"Our class read a biography of Mansa Musa, the ruler of Mali." Using the roots "bio" (life) and "graph" (write), what is a "biography"?', choices: ['a written story of a person\'s life', 'a map of an empire', 'a list of a ruler\'s laws', 'a poem about gold'], answer: 0, explain: '"Bio" means life and "graph" means write, so a biography is a written life story.' },
  { id: 'root-022', skill: 'roots', sub: 'Greek roots', q: '"Germs are microscopic, so you can\'t see them without help." What does "microscopic" most likely mean?', choices: ['very dangerous', 'found only in water', 'too small to see with your eyes alone', 'able to glow in the dark'], answer: 2, explain: '"Micro" means small and "scope" means look at, so microscopic things are too small to see without a microscope.' },
  { id: 'root-023', skill: 'roots', sub: 'Greek roots', q: '"The hydroelectric dam makes power for the whole town." What does "hydroelectric" most likely mean?', choices: ['making electricity from sunlight', 'making electricity from moving water', 'making electricity from wind', 'making electricity from burning coal'], answer: 1, explain: '"Hydro" means water, so hydroelectric power comes from moving water.' },
  { id: 'root-024', skill: 'roots', sub: 'Greek roots', q: '"Ava kept a chronological list of all her dance recitals." What does "chronological" most likely mean?', choices: ['arranged by size', 'arranged from favorite to least favorite', 'arranged in ABC order', 'arranged in time order'], answer: 3, explain: '"Chron" means time, so a chronological list goes in the order things happened.' },
  { id: 'root-025', skill: 'roots', sub: 'Greek roots', q: '"Grandpa\'s old phonograph still plays his records." Using the roots "phon" (sound) and "graph" (write), what does a phonograph do?', choices: ['records and plays sound', 'takes pictures', 'measures heat', 'sends letters far away'], answer: 0, explain: '"Phon" means sound and "graph" means write, so a phonograph "writes" sound onto a record and plays it back.' },
  // roots: Latin roots
  { id: 'root-026', skill: 'roots', sub: 'Latin roots', q: 'The root "port" in "transport" means...', choices: ['break', 'see', 'write', 'carry'], answer: 3, explain: '"Port" means carry. To transport something is to carry it from one place to another.' },
  { id: 'root-027', skill: 'roots', sub: 'Latin roots', q: 'The root "dict" in "predict" means...', choices: ['throw', 'build', 'say', 'hear'], answer: 2, explain: '"Dict" means say. When you predict, you say what will happen before it happens.' },
  { id: 'root-028', skill: 'roots', sub: 'Latin roots', q: 'The root "spect" in "spectator" means...', choices: ['pull', 'look', 'carry', 'speak'], answer: 1, explain: '"Spect" means look. A spectator is someone who watches, or looks at, an event.' },
  { id: 'root-029', skill: 'roots', sub: 'Latin roots', q: 'The root "struct" in "construction" means...', choices: ['break', 'build', 'shape', 'send'], answer: 1, explain: '"Struct" means build. Construction workers build things.' },
  { id: 'root-030', skill: 'roots', sub: 'Latin roots', q: 'The root "rupt" in "erupt" means...', choices: ['throw', 'pull', 'break or burst', 'see'], answer: 2, explain: '"Rupt" means break or burst. When a volcano erupts, lava bursts out.' },
  { id: 'root-031', skill: 'roots', sub: 'Latin roots', q: 'The root "scrib" in "scribble" means...', choices: ['hear', 'carry', 'break', 'write'], answer: 3, explain: '"Scrib" means write. When you scribble, you write or draw quickly and messily.' },
  { id: 'root-032', skill: 'roots', sub: 'Latin roots', q: 'The root "ject" in "eject" means...', choices: ['throw', 'pull', 'look', 'say'], answer: 0, explain: '"Ject" means throw. To eject something is to throw it out, like a disc popping out of a player.' },
  { id: 'root-033', skill: 'roots', sub: 'Latin roots', q: 'The root "tract" in "tractor" means...', choices: ['build', 'throw', 'pull', 'hear'], answer: 2, explain: '"Tract" means pull. A tractor pulls heavy farm equipment.' },
  { id: 'root-034', skill: 'roots', sub: 'Latin roots', q: 'The root "aud" in "audience" means...', choices: ['see', 'hear', 'carry', 'write'], answer: 1, explain: '"Aud" means hear. An audience is a group of people who listen to a show.' },
  { id: 'root-035', skill: 'roots', sub: 'Latin roots', q: 'The root "vis" in "visible" means...', choices: ['hear', 'break', 'pull', 'see'], answer: 3, explain: '"Vis" means see. Something visible can be seen.' },
  { id: 'root-036', skill: 'roots', sub: 'Latin roots', q: 'The root "form" in "transform" means...', choices: ['shape', 'across', 'build', 'speak'], answer: 0, explain: '"Form" means shape. To transform is to change shape ("trans" is the part that means across).' },
  { id: 'root-037', skill: 'roots', sub: 'Latin roots', q: 'Which word contains a root that means "carry"?', choices: ['predict', 'portable', 'inspect', 'erupt'], answer: 1, explain: '"Port" means carry. A portable speaker is easy to carry.' },
  { id: 'root-038', skill: 'roots', sub: 'Latin roots', q: 'Which word contains a root that means "write"?', choices: ['tractor', 'audition', 'manuscript', 'rupture'], answer: 2, explain: '"Script" means write. A manuscript is a book or story written by hand or before it is printed.' },
  { id: 'root-039', skill: 'roots', sub: 'Latin roots', q: 'Which word contains a root that means "break"?', choices: ['disrupt', 'report', 'auditorium', 'describe'], answer: 0, explain: '"Rupt" means break. To disrupt a class is to break up what everyone is doing.' },
  { id: 'root-040', skill: 'roots', sub: 'Latin roots', q: 'Which word contains a root that means "hear"?', choices: ['visible', 'dictionary', 'projector', 'audible'], answer: 3, explain: '"Aud" means hear. An audible sound is loud enough to hear.' },
  { id: 'root-041', skill: 'roots', sub: 'Latin roots', q: 'Which word contains a root that means "throw"?', choices: ['spectacle', 'structure', 'projectile', 'contract'], answer: 2, explain: '"Ject" means throw. A projectile is an object that is thrown or shot forward.' },
  { id: 'root-042', skill: 'roots', sub: 'Latin roots', q: 'Which word contains a root that means "see"?', choices: ['export', 'video', 'dictate', 'traction'], answer: 1, explain: '"Vid" means see. A video is something you watch.' },
  { id: 'root-043', skill: 'roots', sub: 'Latin roots', q: 'Which word contains a root that means "say or speak"?', choices: ['inject', 'import', 'inspect', 'contradict'], answer: 3, explain: '"Dict" means say. To contradict someone is to say the opposite of what they said.' },
  { id: 'root-044', skill: 'roots', sub: 'Latin roots', q: '"Please don\'t interrupt while the principal is speaking at the assembly." What does "interrupt" most likely mean?', choices: ['break in while someone is talking', 'agree loudly', 'listen carefully', 'leave early'], answer: 0, explain: '"Inter" means between and "rupt" means break, so to interrupt is to break in on someone.' },
  { id: 'root-045', skill: 'roots', sub: 'Latin roots', q: '"The coach inspected every helmet before the football game." Using the root "spect" (look), what does "inspected" mean?', choices: ['fixed', 'washed', 'looked at closely', 'painted'], answer: 2, explain: '"Spect" means look, so to inspect is to look at something closely.' },
  { id: 'root-046', skill: 'roots', sub: 'Latin roots', q: '"Our phone charger is portable, so we take it on road trips." What does "portable" most likely mean?', choices: ['easy to carry', 'very expensive', 'broken', 'very loud'], answer: 0, explain: '"Port" means carry and "-able" means able to be, so portable means able to be carried.' },
  { id: 'root-047', skill: 'roots', sub: 'Latin roots', q: '"The magician waved a scarf to distract the crowd so no one saw the coin." Using the root "tract" (pull), what does "distract" mean?', choices: ['make people cheer', 'pull attention away', 'teach a lesson', 'scare people'], answer: 1, explain: '"Tract" means pull, so to distract is to pull someone\'s attention away.' },
  { id: 'root-048', skill: 'roots', sub: 'Latin roots', q: '"The audio on the video game was so quiet that Max turned up the volume." What does "audio" most likely mean?', choices: ['picture', 'story', 'score', 'sound'], answer: 3, explain: '"Aud" means hear, so audio is the sound part of something.' },
  { id: 'root-049', skill: 'roots', sub: 'Latin roots', q: '"Our teacher let us dictate our stories into the tablet instead of typing them." What does "dictate" most likely mean?', choices: ['draw pictures', 'erase mistakes', 'say words out loud so they can be written down', 'read silently'], answer: 2, explain: '"Dict" means say, so to dictate is to say words aloud for someone (or something) to write down.' },
  { id: 'root-050', skill: 'roots', sub: 'Latin roots', q: '"Coach rejected Leo\'s idea to practice in the thunderstorm." Using the root "ject" (throw), what does "rejected" mean?', choices: ['turned down', 'loved', 'copied', 'forgot'], answer: 0, explain: '"Re" means back and "ject" means throw, so to reject an idea is to "throw it back," or turn it down.' },
  // roots: prefixes
  { id: 'root-051', skill: 'roots', sub: 'prefixes', q: 'The prefix "un-" in "unfair" means...', choices: ['again', 'not', 'before', 'too much'], answer: 1, explain: '"Un-" means not, so unfair means not fair.' },
  { id: 'root-052', skill: 'roots', sub: 'prefixes', q: 'Which word has a prefix that means "not"?', choices: ['important', 'imagine', 'improve', 'impossible'], answer: 3, explain: 'In "impossible," "im-" means not: not possible. The other words just start with the letters "im."' },
  { id: 'root-053', skill: 'roots', sub: 'prefixes', q: 'The prefix "mis-" in "misspell" means...', choices: ['again', 'wrongly', 'not', 'before'], answer: 1, explain: '"Mis-" means wrongly or badly, so to misspell is to spell wrong.' },
  { id: 'root-054', skill: 'roots', sub: 'prefixes', q: 'The prefix "dis-" in "disagree" means...', choices: ['the opposite of', 'again', 'together', 'before'], answer: 0, explain: '"Dis-" means not or the opposite of, so disagree means the opposite of agree.' },
  { id: 'root-055', skill: 'roots', sub: 'prefixes', q: 'The prefix "non-" in "nonfiction" means...', choices: ['very', 'before', 'after', 'not'], answer: 3, explain: '"Non-" means not. Nonfiction is writing that is not made up.' },
  { id: 'root-056', skill: 'roots', sub: 'prefixes', q: 'Which word means "not legal"?', choices: ['unlegal', 'dislegal', 'illegal', 'inlegal'], answer: 2, explain: 'Before words that start with "l," the prefix "in-" (not) changes to "il-": illegal.' },
  { id: 'root-057', skill: 'roots', sub: 'prefixes', q: 'Which word means "not responsible"?', choices: ['unresponsible', 'disresponsible', 'irresponsible', 'inresponsible'], answer: 2, explain: 'Before words that start with "r," the prefix "in-" (not) changes to "ir-": irresponsible.' },
  { id: 'root-058', skill: 'roots', sub: 'prefixes', q: 'The prefix "re-" in "rewrite" means...', choices: ['again', 'not', 'before', 'wrongly'], answer: 0, explain: '"Re-" means again, so to rewrite is to write again.' },
  { id: 'root-059', skill: 'roots', sub: 'prefixes', q: 'The prefix "pre-" in "preview" means...', choices: ['after', 'before', 'again', 'not'], answer: 1, explain: '"Pre-" means before. A preview lets you see something before it comes out.' },
  { id: 'root-060', skill: 'roots', sub: 'prefixes', q: '"Jada was so impatient that she opened her birthday present a day early." What does "impatient" mean?', choices: ['very kind', 'super careful', 'really tired', 'not able to wait calmly'], answer: 3, explain: '"Im-" means not, so impatient means not patient, or not able to wait.' },
  // roots: suffixes
  { id: 'root-061', skill: 'roots', sub: 'suffixes', q: 'The suffix "-less" in "fearless" means...', choices: ['full of', 'able to be', 'without', 'one who'], answer: 2, explain: '"-less" means without, so fearless means without fear.' },
  { id: 'root-062', skill: 'roots', sub: 'suffixes', q: 'The suffix "-ful" in "helpful" means...', choices: ['without', 'again', 'not', 'full of'], answer: 3, explain: '"-ful" means full of, so helpful means full of help.' },
  { id: 'root-063', skill: 'roots', sub: 'suffixes', q: 'The suffix "-able" in "washable" means...', choices: ['able to be', 'not', 'the act of', 'full of'], answer: 0, explain: '"-able" means able to be, so a washable shirt is able to be washed.' },
  { id: 'root-064', skill: 'roots', sub: 'suffixes', q: 'The suffix "-ology" in "zoology" means...', choices: ['a fear of', 'the study of', 'a place for', 'a group of'], answer: 1, explain: '"-ology" means the study of. Zoology is the study of animals.' },
  { id: 'root-065', skill: 'roots', sub: 'suffixes', q: 'Adding "-ment" to "excite" makes "excitement." What kind of word is "excitement"?', choices: ['a verb', 'an adjective', 'an adverb', 'a noun'], answer: 3, explain: 'The suffix "-ment" turns a verb into a noun. "Excitement" is a feeling, which is a thing (noun).' },
  { id: 'root-066', skill: 'roots', sub: 'suffixes', q: 'The suffix "-ous" in "dangerous" means...', choices: ['full of', 'without', 'the study of', 'again'], answer: 0, explain: '"-ous" means full of, so dangerous means full of danger.' },
  { id: 'root-067', skill: 'roots', sub: 'suffixes', q: 'The suffix "-tion" turns "invent" into "invention." What does "invention" mean?', choices: ['a person who invents', 'something that was invented', 'able to be invented', 'without inventing'], answer: 1, explain: '"-tion" means the act or result of, so an invention is the result of inventing.' },
  { id: 'root-068', skill: 'roots', sub: 'suffixes', q: 'Which word means "able to be seen"?', choices: ['visual', 'vision', 'visible', 'visitor'], answer: 2, explain: '"Vis" means see and "-ible" means able to be, so visible means able to be seen.' },
  { id: 'root-069', skill: 'roots', sub: 'suffixes', q: '"The puppy was so playful that it chased its tail for ten minutes." What does "playful" mean?', choices: ['full of play', 'without play', 'afraid of playing', 'tired of playing'], answer: 0, explain: '"-ful" means full of, so a playful puppy is full of play.' },
  { id: 'root-070', skill: 'roots', sub: 'suffixes', q: 'Which suffix can you add to "care" to make a word that means "without care"?', choices: ['-ful', '-ment', '-able', '-less'], answer: 3, explain: '"-less" means without, so careless means without care.' },
  // context
  { id: 'ctx-001', skill: 'context', q: 'The forecast called for "torrential" rain, so the soccer game was canceled before the field could flood. What does "torrential" most likely mean?', choices: ['light and gentle', 'freezing cold', 'very heavy', 'quick and short'], answer: 2, explain: 'The clue is that the field could flood. Only very heavy rain floods a field.' },
  { id: 'ctx-002', skill: 'context', q: 'After running the mile, Sam was "famished" and ate three sandwiches. What does "famished" most likely mean?', choices: ['very proud', 'very hungry', 'very cold', 'very bored'], answer: 1, explain: 'Eating three sandwiches is the clue: Sam was very hungry.' },
  { id: 'ctx-003', skill: 'context', q: 'The "arid" desert gets less than ten inches of rain a year. What does "arid" most likely mean?', choices: ['very windy', 'very dry', 'crowded', 'very green'], answer: 1, explain: 'Getting almost no rain is the clue that arid means very dry.' },
  { id: 'ctx-004', skill: 'context', q: 'Mansa Musa was so "affluent" that he gave away gold everywhere he traveled. What does "affluent" most likely mean?', choices: ['rich', 'lost', 'angry', 'sleepy'], answer: 0, explain: 'Only someone very rich could give away gold everywhere, so affluent means rich.' },
  { id: 'ctx-005', skill: 'context', q: 'The explorers\' food supply "dwindled" until only a few crackers were left. What does "dwindled" most likely mean?', choices: ['got heavier', 'got colder', 'got more expensive', 'got smaller little by little'], answer: 3, explain: '"Until only a few crackers were left" shows the supply kept shrinking.' },
  { id: 'ctx-006', skill: 'context', q: 'Lila was "reluctant" to jump off the high dive, so she stood at the edge for ten minutes. What does "reluctant" most likely mean?', choices: ['excited', 'late', 'unwilling or not sure', 'proud'], answer: 2, explain: 'Standing at the edge for ten minutes shows Lila did not want to jump yet.' },
  { id: 'ctx-007', skill: 'context', q: 'The colonists had few coins, so they had to "barter," trading corn and furs for tools. What does "barter" most likely mean?', choices: ['steal from others', 'build new houses', 'trade goods without using money', 'plant crops'], answer: 2, explain: 'The sentence explains it: they traded corn and furs instead of using coins.' },
  { id: 'ctx-008', skill: 'context', q: 'Our dog is usually "docile," but he barks wildly at the mail carrier. What does "docile" most likely mean?', choices: ['loud', 'calm and gentle', 'hungry', 'fast'], answer: 1, explain: 'The word "but" signals a contrast. The opposite of barking wildly is being calm and gentle.' },
  { id: 'ctx-009', skill: 'context', q: 'The new video game was "ubiquitous"; it seemed like every kid at school was playing it. What does "ubiquitous" most likely mean?', choices: ['found everywhere', 'hard to win', 'too expensive', 'very short'], answer: 0, explain: 'If every kid seems to have it, the game is everywhere.' },
  { id: 'ctx-010', skill: 'context', q: 'The dancer\'s movements were so "fluid" that she seemed to flow across the stage like water. What does "fluid" most likely mean here?', choices: ['stiff and jerky', 'wet', 'loud', 'smooth and graceful'], answer: 3, explain: '"Flow across the stage like water" tells you her movements were smooth. She was not actually wet.' },
  { id: 'ctx-011', skill: 'context', q: 'The hikers were "apprehensive" about crossing the shaky rope bridge. What does "apprehensive" most likely mean?', choices: ['thrilled', 'bored', 'nervous', 'lazy'], answer: 2, explain: 'A shaky rope bridge would make most people nervous.' },
  { id: 'ctx-012', skill: 'context', q: 'The instructions were so "ambiguous" that half the class built the project one way and half built it another way. What does "ambiguous" most likely mean?', choices: ['very long', 'unclear', 'printed in color', 'easy to follow'], answer: 1, explain: 'People understood the directions in two different ways, so they were unclear.' },
  { id: 'ctx-013', skill: 'context', q: 'After the storm, the town was "desolate," with empty streets and broken windows. What does "desolate" most likely mean?', choices: ['crowded', 'newly built', 'cheerful', 'empty and ruined'], answer: 3, explain: 'Empty streets and broken windows describe a place that is empty and ruined.' },
  { id: 'ctx-014', skill: 'context', q: 'Unlike his "boisterous" little brother, Theo is quiet in the library. What does "boisterous" most likely mean?', choices: ['loud and rowdy', 'shy', 'clever', 'small'], answer: 0, explain: '"Unlike" signals a contrast with quiet Theo, so boisterous means loud and rowdy.' },
  { id: 'ctx-015', skill: 'context', q: 'The scientist had to "verify" her results by running the experiment again. What does "verify" most likely mean?', choices: ['check that something is true', 'forget', 'hide', 'guess'], answer: 0, explain: 'Running the experiment again is a way to check that the results are true.' },
  { id: 'ctx-016', skill: 'context', q: 'Ben\'s excuse was "plausible," so the teacher believed him. What does "plausible" most likely mean?', choices: ['silly', 'rude', 'believable', 'long'], answer: 2, explain: 'The teacher believed him, so the excuse was believable.' },
  { id: 'ctx-017', skill: 'context', q: 'The lake was so "tranquil" that it looked like a mirror. What does "tranquil" most likely mean?', choices: ['stormy', 'deep', 'dirty', 'calm and still'], answer: 3, explain: 'Water only looks like a mirror when it is calm and still.' },
  { id: 'ctx-018', skill: 'context', q: 'The hurricane\'s winds were so "ferocious" that they ripped trees out of the ground. What does "ferocious" most likely mean?', choices: ['gentle', 'fierce and powerful', 'warm', 'slow'], answer: 1, explain: 'Winds that rip trees out of the ground are fierce and powerful.' },
  { id: 'ctx-019', skill: 'context', q: 'Grandma "meticulously" folded each paper crane, making sure every corner lined up perfectly. What does "meticulously" most likely mean?', choices: ['very carefully', 'quickly', 'sadly', 'loudly'], answer: 0, explain: 'Making every corner line up perfectly takes great care.' },
  { id: 'ctx-020', skill: 'context', q: 'When the bus broke down, the field trip was "postponed" until next Friday. What does "postponed" most likely mean?', choices: ['canceled forever', 'made shorter', 'moved to a later time', 'moved indoors'], answer: 2, explain: '"Until next Friday" shows the trip will still happen, just later.' },
  { id: 'ctx-021', skill: 'context', q: 'The coach "commended" the team for their hard work and gave everyone a high five. What does "commended" most likely mean?', choices: ['punished', 'praised', 'ignored', 'tricked'], answer: 1, explain: 'High fives for hard work show the coach was praising the team.' },
  { id: 'ctx-022', skill: 'context', q: 'Ghana\'s traders grew "prosperous" by selling gold and salt along busy trade routes. What does "prosperous" most likely mean?', choices: ['tired', 'lost', 'unkind', 'successful and wealthy'], answer: 3, explain: 'Selling gold and salt on busy routes made the traders successful and rich.' },
  { id: 'ctx-023', skill: 'context', q: 'The owl is "nocturnal," sleeping all day and hunting at night. What does "nocturnal" most likely mean?', choices: ['friendly', 'wild', 'active at night', 'hungry'], answer: 2, explain: 'The owl hunts at night, so nocturnal means active at night.' },
  { id: 'ctx-024', skill: 'context', q: 'The "abundant" harvest meant the colonists had more corn than they could eat. What does "abundant" most likely mean?', choices: ['more than enough', 'very small', 'rotten', 'late'], answer: 0, explain: '"More corn than they could eat" means there was more than enough.' },
  { id: 'ctx-025', skill: 'context', q: 'My little sister is "inquisitive"; she asks a hundred questions every day. What does "inquisitive" most likely mean?', choices: ['grumpy', 'curious', 'sleepy', 'quiet'], answer: 1, explain: 'Someone who asks lots of questions is curious.' },
  // figurative
  { id: 'fig-001', skill: 'figurative', q: 'What type of figurative language is this? "The wind whispered secrets to the trees."', choices: ['simile', 'metaphor', 'hyperbole', 'personification'], answer: 3, explain: 'Wind can\'t really whisper or keep secrets. Giving human actions to a non-human thing is personification.' },
  { id: 'fig-002', skill: 'figurative', q: 'What type of figurative language is this? "My backpack weighs a thousand pounds."', choices: ['metaphor', 'simile', 'personification', 'hyperbole'], answer: 3, explain: 'No backpack weighs a thousand pounds. A huge exaggeration is hyperbole.' },
  { id: 'fig-003', skill: 'figurative', q: 'What type of figurative language is this? "Her voice was as smooth as honey."', choices: ['metaphor', 'simile', 'personification', 'alliteration'], answer: 1, explain: 'It compares two things using "as," so it is a simile.' },
  { id: 'fig-004', skill: 'figurative', q: 'What type of figurative language is this? "The classroom was a zoo after the fire drill."', choices: ['metaphor', 'simile', 'onomatopoeia', 'personification'], answer: 0, explain: 'It says the classroom WAS a zoo without using "like" or "as," so it is a metaphor.' },
  { id: 'fig-005', skill: 'figurative', q: 'What type of figurative language is this? "Buzz! The alarm clock went off."', choices: ['alliteration', 'simile', 'onomatopoeia', 'idiom'], answer: 2, explain: '"Buzz" is a word that sounds like the noise it names. That is onomatopoeia.' },
  { id: 'fig-006', skill: 'figurative', q: 'What type of figurative language is this? "Silly snakes slither slowly."', choices: ['onomatopoeia', 'alliteration', 'simile', 'metaphor'], answer: 1, explain: 'Every word starts with the same "s" sound. Repeating beginning sounds is alliteration.' },
  { id: 'fig-007', skill: 'figurative', q: 'What type of figurative language is this? "It\'s raining cats and dogs."', choices: ['simile', 'onomatopoeia', 'alliteration', 'idiom'], answer: 3, explain: 'It means "raining very hard," not that animals are falling. A saying whose meaning differs from its words is an idiom.' },
  { id: 'fig-008', skill: 'figurative', q: 'What type of figurative language is this? "The old car coughed and wheezed up the hill."', choices: ['simile', 'alliteration', 'personification', 'idiom'], answer: 2, explain: 'Cars can\'t cough or wheeze like people. Giving a thing human actions is personification.' },
  { id: 'fig-009', skill: 'figurative', q: 'What type of figurative language is this? "Dad\'s snoring sounded like a freight train."', choices: ['simile', 'metaphor', 'personification', 'alliteration'], answer: 0, explain: 'It compares snoring to a train using "like," so it is a simile.' },
  { id: 'fig-010', skill: 'figurative', q: 'What type of figurative language is this? "Time is a thief."', choices: ['metaphor', 'simile', 'onomatopoeia', 'alliteration'], answer: 0, explain: 'It says time IS a thief without "like" or "as." That direct comparison is a metaphor.' },
  { id: 'fig-011', skill: 'figurative', q: 'What type of figurative language is this? "I\'ve told you a million times to clean your room!"', choices: ['simile', 'personification', 'onomatopoeia', 'hyperbole'], answer: 3, explain: 'Nobody has said something a million times. That exaggeration is hyperbole.' },
  { id: 'fig-012', skill: 'figurative', q: 'What type of figurative language is this? "The leaves danced in the breeze."', choices: ['simile', 'personification', 'hyperbole', 'onomatopoeia'], answer: 1, explain: 'Leaves can\'t really dance. Giving them a human action is personification.' },
  { id: 'fig-013', skill: 'figurative', q: 'What type of figurative language is this? "Break a leg at your dance recital!"', choices: ['hyperbole', 'personification', 'idiom', 'simile'], answer: 2, explain: '"Break a leg" means "good luck," not "get hurt." That makes it an idiom.' },
  { id: 'fig-014', skill: 'figurative', q: 'What type of figurative language is this? "The bacon sizzled in the pan."', choices: ['personification', 'simile', 'onomatopoeia', 'hyperbole'], answer: 2, explain: '"Sizzled" sounds like the noise bacon makes when it cooks. That is onomatopoeia.' },
  { id: 'fig-015', skill: 'figurative', q: 'What type of figurative language is this? "Peter\'s pet parrot picked purple peppers."', choices: ['onomatopoeia', 'alliteration', 'idiom', 'simile'], answer: 1, explain: 'Most of the words start with the "p" sound. That repeated beginning sound is alliteration.' },
  { id: 'fig-016', skill: 'figurative', q: 'What type of figurative language is this? "The snow was a white blanket over the town."', choices: ['metaphor', 'simile', 'personification', 'idiom'], answer: 0, explain: 'It says the snow WAS a blanket without "like" or "as," so it is a metaphor.' },
  { id: 'fig-017', skill: 'figurative', q: 'What type of figurative language is this? "The goalie was as quick as a cat."', choices: ['metaphor', 'hyperbole', 'idiom', 'simile'], answer: 3, explain: 'It compares the goalie to a cat using "as," so it is a simile.' },
  { id: 'fig-018', skill: 'figurative', q: 'What type of figurative language is this? "When the teacher said \'pop quiz,\' my heart stopped."', choices: ['hyperbole', 'simile', 'personification', 'alliteration'], answer: 0, explain: 'The writer\'s heart didn\'t really stop. That exaggeration shows how surprised they were, so it is hyperbole.' },
  { id: 'fig-019', skill: 'figurative', q: '"Mia had butterflies in her stomach before the dance recital." What does this mean?', choices: ['She was hungry.', 'She felt nervous.', 'She swallowed a bug.', 'She loved nature.'], answer: 1, explain: '"Butterflies in your stomach" is an idiom for the fluttery feeling of being nervous.' },
  { id: 'fig-020', skill: 'figurative', q: '"That math test was a piece of cake." What does this mean?', choices: ['The test was very hard.', 'The test was given at a party.', 'The test was very easy.', 'The test made everyone hungry.'], answer: 2, explain: '"A piece of cake" is an idiom that means something is very easy.' },
  { id: 'fig-021', skill: 'figurative', q: '"Jamal spilled the beans about the surprise party." What does this mean?', choices: ['He made a mess.', 'He cooked dinner.', 'He canceled the party.', 'He told the secret.'], answer: 3, explain: '"Spill the beans" is an idiom that means tell a secret.' },
  { id: 'fig-022', skill: 'figurative', q: '"The sun smiled down on our soccer game." What does this personification tell you?', choices: ['It was a cloudy day.', 'The sun was shining brightly.', 'The game was canceled.', 'The sun was setting.'], answer: 1, explain: 'A smiling sun suggests a bright, cheerful, sunny day.' },
  { id: 'fig-023', skill: 'figurative', q: '"My brother is a couch potato on weekends." What does this metaphor mean?', choices: ['He loves to eat potatoes.', 'He sleeps outside.', 'He sits around and doesn\'t move much.', 'He is a great cook.'], answer: 2, explain: 'A "couch potato" is someone who sits on the couch a lot, like a lazy lump.' },
  { id: 'fig-024', skill: 'figurative', q: '"Mom told me to hit the books before my science test." What does "hit the books" mean?', choices: ['study hard', 'knock books off the desk', 'return library books', 'buy new books'], answer: 0, explain: '"Hit the books" is an idiom that means study.' },
  { id: 'fig-025', skill: 'figurative', q: '"The new student was as cool as a cucumber during her first speech." What does this mean?', choices: ['She was cold.', 'She was wearing green.', 'She was nervous.', 'She was calm and relaxed.'], answer: 3, explain: '"Cool as a cucumber" is a simile that means very calm, even under pressure.' },
  { id: 'fig-026', skill: 'figurative', q: '"Your room is a pigsty!" What does this metaphor mean?', choices: ['The room is very messy.', 'The room is full of pigs.', 'The room is very small.', 'The room is cozy.'], answer: 0, explain: 'A pigsty is a pig pen, which is dirty and messy, so the room is very messy.' },
  { id: 'fig-027', skill: 'figurative', q: '"The thunder grumbled in the distance." What does "grumbled" suggest about the thunder?', choices: ['It was loud and right overhead.', 'It had stopped.', 'It sounded happy.', 'It made a low, rumbling sound.'], answer: 3, explain: 'People grumble in low, cranky voices, so the thunder made a low rumble far away.' },
  { id: 'fig-028', skill: 'figurative', q: '"I\'m so hungry I could eat a horse." What does this hyperbole mean?', choices: ['I like horses.', 'I am very hungry.', 'I already ate a lot.', 'I want to go horseback riding.'], answer: 1, explain: 'Nobody could eat a horse. The exaggeration shows the speaker is very hungry.' },
  { id: 'fig-029', skill: 'figurative', q: '"Leo was on cloud nine after scoring the winning goal." What does this mean?', choices: ['He was confused.', 'He was sleepy.', 'He was extremely happy.', 'He was high up in the air.'], answer: 2, explain: '"On cloud nine" is an idiom that means extremely happy.' },
  { id: 'fig-030', skill: 'figurative', q: '"Don\'t let the cat out of the bag about Mom\'s birthday gift." What does this mean?', choices: ['Don\'t tell the secret.', 'Don\'t let the pet outside.', 'Don\'t open the gift early.', 'Don\'t lose the gift bag.'], answer: 0, explain: '"Let the cat out of the bag" is an idiom that means accidentally tell a secret.' },
  // conventions: pronoun case
  { id: 'conv-001', skill: 'conventions', sub: 'pronoun case', q: 'Choose the word that completes the sentence: "Coach gave the trophy to Maya and ___."', choices: ['I', 'myself', 'me', 'mine'], answer: 2, explain: 'Rule: after a preposition like "to," use an object pronoun. Cover up "Maya and": "Coach gave the trophy to me."' },
  { id: 'conv-002', skill: 'conventions', sub: 'pronoun case', q: 'Choose the word that completes the sentence: "___ and Jordan practiced the dance routine after school."', choices: ['Her', 'She', 'Herself', 'Hers'], answer: 1, explain: 'Rule: the subject of a sentence needs a subject pronoun. Cover up "and Jordan": "She practiced," not "Her practiced."' },
  { id: 'conv-003', skill: 'conventions', sub: 'pronoun case', q: 'Which sentence is written correctly?', choices: ['Me and Ella went to the skate park.', 'Ella and me went to the skate park.', 'Ella and myself went to the skate park.', 'Ella and I went to the skate park.'], answer: 3, explain: 'Rule: use the subject pronoun "I" for the subject. Test it alone: "I went," not "me went." It is polite to name the other person first.' },
  { id: 'conv-004', skill: 'conventions', sub: 'pronoun case', q: 'Choose the word that completes the sentence: "The puppy followed Liam and ___ all the way home."', choices: ['she', 'her', 'they', 'herself'], answer: 1, explain: 'Rule: the person receiving the action needs an object pronoun. Test it alone: "The puppy followed her."' },
  { id: 'conv-005', skill: 'conventions', sub: 'pronoun case', q: 'Choose the word that completes the sentence: "Between you and ___, I think the movie was too long."', choices: ['I', 'myself', 'mine', 'me'], answer: 3, explain: 'Rule: "between" is a preposition, so it takes object pronouns: "between you and me."' },
  { id: 'conv-006', skill: 'conventions', sub: 'pronoun case', q: 'Choose the word that completes the sentence: "Mr. Lopez asked ___ students to stack the chairs."', choices: ['us', 'we', 'ourselves', 'they'], answer: 0, explain: 'Rule: the people being asked are objects, so use "us." Test it without "students": "Mr. Lopez asked us."' },
  { id: 'conv-007', skill: 'conventions', sub: 'pronoun case', q: 'Choose the word that completes the sentence: "___ sixth graders won the field day relay."', choices: ['Us', 'Ourselves', 'We', 'Them'], answer: 2, explain: 'Rule: the subject needs a subject pronoun. Test it without "sixth graders": "We won," not "Us won."' },
  { id: 'conv-008', skill: 'conventions', sub: 'pronoun case', q: 'Which sentence is written correctly?', choices: ['Grandma baked cookies for my brother and I.', 'Grandma baked cookies for I and my brother.', 'Grandma baked cookies for my brother and me.', 'Grandma baked cookies for myself and my brother.'], answer: 2, explain: 'Rule: after the preposition "for," use the object pronoun "me." Test it alone: "Grandma baked cookies for me."' },
  { id: 'conv-009', skill: 'conventions', sub: 'pronoun case', q: 'Choose the word that completes the sentence: "___ left a backpack on the bus?"', choices: ['Who', 'Whom', 'Whose', 'Which'], answer: 0, explain: 'Rule: "who" is the subject form and "whom" is the object form. The question needs a subject (the person who left it), so use "who."' },
  // conventions: pronoun consistency
  { id: 'conv-010', skill: 'conventions', sub: 'pronoun consistency', q: 'Which sentence is written correctly?', choices: ['When you practice piano every day, we get better fast.', 'When you practice piano every day, they get better fast.', 'When one practices piano every day, you get better fast.', 'When you practice piano every day, you get better fast.'], answer: 3, explain: 'Rule: don\'t switch pronouns partway through a sentence. It starts with "you," so it should keep using "you."' },
  { id: 'conv-011', skill: 'conventions', sub: 'pronoun consistency', q: 'Choose the word that completes the sentence: "The cookies were burned, so Dad threw ___ away."', choices: ['it', 'them', 'they', 'him'], answer: 1, explain: 'Rule: a pronoun must match the noun it replaces. "Cookies" is plural, so use the plural object pronoun "them."' },
  { id: 'conv-012', skill: 'conventions', sub: 'pronoun consistency', q: 'Choose the word that completes the sentence: "If students want to join the robotics club, ___ should sign up by Friday."', choices: ['you', 'it', 'they', 'he'], answer: 2, explain: 'Rule: keep pronouns consistent with the noun. "Students" is plural and third person, so use "they."' },
  { id: 'conv-013', skill: 'conventions', sub: 'pronoun consistency', q: 'Which sentence is written correctly?', choices: ['I love dance class because you get to learn new routines.', 'I love dance class because me get to learn new routines.', 'I love dance class because I gets to learn new routines.', 'I love dance class because I get to learn new routines.'], answer: 3, explain: 'Rule: keep the same pronoun all the way through. The sentence starts with "I," so it should keep using "I" (and "I get," not "I gets").' },
  { id: 'conv-014', skill: 'conventions', sub: 'pronoun consistency', q: 'Choose the word that completes the sentence: "My dog wagged ___ tail when I got home."', choices: ['its', 'it\'s', 'their', 'your'], answer: 0, explain: 'Rule: the pronoun must match "dog," which is one animal, so use "its." "It\'s" means "it is."' },
  { id: 'conv-015', skill: 'conventions', sub: 'pronoun consistency', q: 'Which revision fixes the pronoun shift? "When we got to the museum, you had to check your coats at the door."', choices: ['When we got to the museum, you had to check our coats at the door.', 'When we got to the museum, we had to check our coats at the door.', 'When you got to the museum, we had to check your coats at the door.', 'When we got to the museum, they had to check your coats at the door.'], answer: 1, explain: 'Rule: don\'t shift pronouns. The sentence is about "we," so it should use "we" and "our" all the way through.' },
  { id: 'conv-016', skill: 'conventions', sub: 'pronoun consistency', q: 'Choose the word that completes the sentence: "The twins forgot ___ own sleeping bags."', choices: ['her', 'its', 'his', 'their'], answer: 3, explain: 'Rule: a pronoun must agree in number with its noun. "Twins" is plural, so use "their."' },
  { id: 'conv-017', skill: 'conventions', sub: 'pronoun consistency', q: 'Choose the word that completes the sentence: "Players should wear mouth guards when ___ play hockey."', choices: ['you', 'they', 'it', 'he'], answer: 1, explain: 'Rule: the pronoun must match "players," which is plural and third person, so use "they."' },
  // conventions: verb tense
  { id: 'conv-018', skill: 'conventions', sub: 'verb tense', q: 'Which sentence is written correctly?', choices: ['Yesterday Nia walks to school and forgot her lunch.', 'Yesterday Nia walked to school and forgets her lunch.', 'Yesterday Nia walked to school and forgot her lunch.', 'Yesterday Nia will walk to school and forgot her lunch.'], answer: 2, explain: 'Rule: keep verb tense consistent. "Yesterday" means the past, so both verbs should be past tense: walked, forgot.' },
  { id: 'conv-019', skill: 'conventions', sub: 'verb tense', q: 'Choose the word that completes the sentence: "Last summer, our family ___ to the beach in Virginia."', choices: ['drove', 'drives', 'will drive', 'driving'], answer: 0, explain: 'Rule: "Last summer" tells you it already happened, so use the past tense "drove."' },
  { id: 'conv-020', skill: 'conventions', sub: 'verb tense', q: 'Choose the words that complete the sentence: "Tomorrow the band ___ in the parade."', choices: ['marched', 'has marched', 'marching', 'will march'], answer: 3, explain: 'Rule: "Tomorrow" is the future, so use the future tense "will march."' },
  { id: 'conv-021', skill: 'conventions', sub: 'verb tense', q: 'Which revision fixes the tense shift? "During the game, Eli dribbles down the court and shot the ball."', choices: ['During the game, Eli dribbled down the court and shot the ball.', 'During the game, Eli dribbles down the court and shooted the ball.', 'During the game, Eli dribbled down the court and shoots the ball.', 'During the game, Eli dribble down the court and shot the ball.'], answer: 0, explain: 'Rule: verbs in the same sentence should stay in the same tense. "Dribbled" and "shot" are both past tense.' },
  { id: 'conv-022', skill: 'conventions', sub: 'verb tense', q: 'Choose the word that completes the sentence: "By the time we arrived, the movie ___ already started."', choices: ['has', 'had', 'have', 'will'], answer: 1, explain: 'Rule: use "had" for something that happened before another past event. The movie started before we arrived.' },
  { id: 'conv-023', skill: 'conventions', sub: 'verb tense', q: 'Which sentence is written correctly?', choices: ['I have saw that movie three times.', 'I seen that movie three times.', 'I have seen that movie three times.', 'I have see that movie three times.'], answer: 2, explain: 'Rule: helping verbs "have" and "has" go with the past participle "seen," never "saw."' },
  { id: 'conv-024', skill: 'conventions', sub: 'verb tense', q: 'Choose the word that completes the sentence: "Every morning, my cat ___ on my face to wake me up."', choices: ['sitting', 'sit', 'sits', 'have sat'], answer: 2, explain: 'Rule: "Every morning" describes something that happens again and again, so use the present tense. "Cat" is singular, so it is "sits."' },
  { id: 'conv-025', skill: 'conventions', sub: 'verb tense', q: 'Which revision fixes the tense shift? "The colonists planted corn in the spring, and in the fall they harvest it."', choices: ['The colonists planted corn in the spring, and in the fall they harvested it.', 'The colonists plant corn in the spring, and in the fall they harvested it.', 'The colonists planted corn in the spring, and in the fall they will harvest it.', 'The colonists planting corn in the spring, and in the fall they harvest it.'], answer: 0, explain: 'Rule: keep the tense consistent. The colonists lived long ago, so both verbs should be past tense: planted, harvested.' },
  { id: 'conv-026', skill: 'conventions', sub: 'verb tense', q: 'Choose the word that completes the sentence: "Yesterday I ___ my science project to class."', choices: ['bringed', 'brought', 'brung', 'bring'], answer: 1, explain: 'Rule: "bring" is an irregular verb. Its past tense is "brought."' },
  // conventions: parenthetical punctuation
  { id: 'conv-027', skill: 'conventions', sub: 'parenthetical punctuation', q: 'Which sentence uses commas correctly to set off extra information?', choices: ['My best friend Kayla, loves hip-hop dance.', 'My, best friend Kayla loves hip-hop dance.', 'My best friend Kayla loves, hip-hop dance.', 'My best friend, Kayla, loves hip-hop dance.'], answer: 3, explain: 'Rule: extra information that renames a noun goes between a PAIR of commas. "Kayla" renames "my best friend."' },
  { id: 'conv-028', skill: 'conventions', sub: 'parenthetical punctuation', q: 'Which sentence uses parentheses correctly?', choices: ['The Mali Empire (in West Africa grew rich from gold.)', 'The Mali (Empire in West Africa) grew rich from gold.', 'The Mali Empire (in West Africa) grew rich from gold.', 'The Mali Empire in (West Africa) grew rich from gold.'], answer: 2, explain: 'Rule: parentheses go around extra information. You should be able to remove it and still have a complete sentence: "The Mali Empire grew rich from gold."' },
  { id: 'conv-029', skill: 'conventions', sub: 'parenthetical punctuation', q: 'Which sentence uses dashes correctly?', choices: ['Our dog a fluffy\u2014golden retriever\u2014loves the snow.', 'Our\u2014dog a fluffy golden retriever\u2014loves the snow.', 'Our dog\u2014a fluffy golden retriever loves the snow.', 'Our dog\u2014a fluffy golden retriever\u2014loves the snow.'], answer: 3, explain: 'Rule: a pair of dashes goes around the whole interrupting phrase. Take it out and the sentence still works: "Our dog loves the snow."' },
  { id: 'conv-030', skill: 'conventions', sub: 'parenthetical punctuation', q: 'Which punctuation correctly completes the sentence? "Ms. Patel ___ our science teacher ___ let us launch rockets."', choices: ['a comma in each blank', 'a semicolon in each blank', 'a colon in each blank', 'a period in each blank'], answer: 0, explain: 'Rule: "our science teacher" is extra information that renames Ms. Patel, so it goes between a pair of commas.' },
  { id: 'conv-031', skill: 'conventions', sub: 'parenthetical punctuation', q: 'Which sentence is punctuated correctly?', choices: ['The volcano which had been quiet for years, suddenly erupted.', 'The volcano, which had been quiet for years, suddenly erupted.', 'The volcano, which had been quiet for years suddenly erupted.', 'The volcano which, had been quiet for years suddenly erupted.'], answer: 1, explain: 'Rule: an interrupting "which" phrase needs a comma at BOTH ends. Remove it and you get "The volcano suddenly erupted."' },
  { id: 'conv-032', skill: 'conventions', sub: 'parenthetical punctuation', q: 'Which sentence uses parentheses correctly?', choices: ['Marcus scored three goals (a new team record in Saturday\'s game.', 'Marcus scored three goals (a new team record) in Saturday\'s game.', 'Marcus (scored three goals) a new team record in Saturday\'s game.', 'Marcus scored three goals) a new team record (in Saturday\'s game.'], answer: 1, explain: 'Rule: parentheses come in pairs around extra information. Remove "(a new team record)" and the sentence still makes sense.' },
  { id: 'conv-033', skill: 'conventions', sub: 'parenthetical punctuation', q: 'Why does this sentence use commas? "Our principal, Dr. Green, read the morning announcements."', choices: ['to separate items in a list', 'to join two complete sentences', 'to set off extra information that renames the principal', 'to show a pause before a quotation'], answer: 2, explain: 'Rule: an appositive (a phrase that renames a noun) is set off with commas. "Dr. Green" renames "our principal."' },
  { id: 'conv-034', skill: 'conventions', sub: 'parenthetical punctuation', q: 'Which sentence uses dashes correctly?', choices: ['The final level\u2014the one with the lava dragon, took me two hours to beat.', 'The final level the one\u2014with the lava dragon\u2014took me two hours to beat.', 'The final\u2014level the one with the lava dragon\u2014took me two hours to beat.', 'The final level\u2014the one with the lava dragon\u2014took me two hours to beat.'], answer: 3, explain: 'Rule: use a matching pair of dashes (not a dash and a comma) around the whole interruption.' },
  { id: 'conv-035', skill: 'conventions', sub: 'parenthetical punctuation', q: 'Which sentence is punctuated correctly?', choices: ['My little brother, of course, wanted the biggest slice.', 'My little brother of course, wanted the biggest slice.', 'My little brother, of course wanted the biggest slice.', 'My, little brother of course wanted the biggest slice.'], answer: 0, explain: 'Rule: an interrupting phrase like "of course" needs a comma before it and after it.' },
  // conventions: commas
  { id: 'conv-036', skill: 'conventions', sub: 'commas', q: 'Which sentence uses commas correctly?', choices: ['We packed sunscreen towels, and snacks for the beach.', 'We packed, sunscreen, towels, and snacks for the beach.', 'We packed sunscreen, towels and, snacks for the beach.', 'We packed sunscreen, towels, and snacks for the beach.'], answer: 3, explain: 'Rule: use commas to separate items in a list. No comma goes between the verb "packed" and the list.' },
  { id: 'conv-037', skill: 'conventions', sub: 'commas', q: 'Which sentence is punctuated correctly?', choices: ['I wanted to play outside but, it started to rain.', 'I wanted to play outside, but it started to rain.', 'I wanted, to play outside but it started to rain.', 'I wanted to play, outside but it started to rain.'], answer: 1, explain: 'Rule: when "but" joins two complete sentences, put the comma BEFORE "but."' },
  { id: 'conv-038', skill: 'conventions', sub: 'commas', q: 'Which sentence is punctuated correctly?', choices: ['After the game, we went out for pizza.', 'After the game we went, out for pizza.', 'After, the game we went out for pizza.', 'After the game we, went out for pizza.'], answer: 0, explain: 'Rule: put a comma after an introductory phrase like "After the game."' },
  { id: 'conv-039', skill: 'conventions', sub: 'commas', q: 'Which sentence uses a comma correctly?', choices: ['Jake can you, pass me the controller?', 'Jake can you pass me, the controller?', 'Jake, can you pass me the controller?', 'Jake can, you pass me the controller?'], answer: 2, explain: 'Rule: when you speak directly to someone by name, set the name off with a comma.' },
  { id: 'conv-040', skill: 'conventions', sub: 'commas', q: 'Which sentence is punctuated correctly?', choices: ['On July 4, 1776, the colonies declared independence.', 'On July, 4 1776 the colonies declared independence.', 'On July 4 1776, the colonies declared independence.', 'On July 4, 1776 the colonies, declared independence.'], answer: 0, explain: 'Rule: in a date, put a comma between the day and the year, and another comma after the year when the sentence keeps going.' },
  { id: 'conv-041', skill: 'conventions', sub: 'commas', q: 'Which sentence is punctuated correctly?', choices: ['Our class visited, Richmond Virginia on a field trip.', 'Our class visited Richmond Virginia, on a field trip.', 'Our, class visited Richmond, Virginia, on a field trip.', 'Our class visited Richmond, Virginia, on a field trip.'], answer: 3, explain: 'Rule: put a comma between a city and its state, and another comma after the state when the sentence keeps going.' },
  { id: 'conv-042', skill: 'conventions', sub: 'commas', q: 'Which sentence is punctuated correctly?', choices: ['"Let\'s go to the park" said, Mom.', '"Let\'s go to the park," said Mom.', '"Let\'s go to the park." said Mom.', '"Let\'s go to the park", said Mom.'], answer: 1, explain: 'Rule: when a quotation comes before "said," end it with a comma placed INSIDE the closing quotation mark.' },
  { id: 'conv-043', skill: 'conventions', sub: 'commas', q: 'Which sentence is punctuated correctly?', choices: ['Yes I, finished my homework.', 'Yes I finished, my homework.', 'Yes, I finished my homework.', 'Yes I finished my homework,'], answer: 2, explain: 'Rule: put a comma after an introductory word like "yes," "no," or "well."' },
  // conventions: run-ons and fragments
  { id: 'conv-044', skill: 'conventions', sub: 'run-ons and fragments', q: 'Which revision fixes the run-on? "I love soccer my sister loves basketball."', choices: ['I love soccer, my sister loves basketball.', 'I love soccer but, my sister loves basketball.', 'I love soccer my sister, loves basketball.', 'I love soccer, but my sister loves basketball.'], answer: 3, explain: 'Rule: join two complete sentences with a comma AND a joining word like "but." A comma alone makes a comma splice.' },
  { id: 'conv-045', skill: 'conventions', sub: 'run-ons and fragments', q: 'Which of these is a complete sentence?', choices: ['Because the bus was late.', 'When the bus finally got to school.', 'The bus was late.', 'Running to catch the late bus.'], answer: 2, explain: 'Rule: a complete sentence has a subject and a verb and expresses a complete thought. The others leave you waiting for more, so they are fragments.' },
  { id: 'conv-046', skill: 'conventions', sub: 'run-ons and fragments', q: 'Which revision fixes the run-on? "The storm knocked out the power we played board games by flashlight."', choices: ['The storm knocked out the power, we played board games by flashlight.', 'The storm knocked out the power. We played board games by flashlight.', 'The storm knocked out the power we played. Board games by flashlight.', 'The storm knocked out, the power we played board games by flashlight.'], answer: 1, explain: 'Rule: a run-on squeezes two sentences together. Split them with a period where one complete thought ends.' },
  { id: 'conv-047', skill: 'conventions', sub: 'run-ons and fragments', q: 'Which revision fixes the fragment? "After we finished our science project."', choices: ['After we finished our science project, we cleaned up the table.', 'After we finished. Our science project.', 'After we finished our science project and the table.', 'We finished. After our science project.'], answer: 0, explain: 'Rule: a fragment is missing a complete thought. Adding a main clause ("we cleaned up the table") finishes the thought.' },
  { id: 'conv-048', skill: 'conventions', sub: 'run-ons and fragments', q: 'Which sentence is a run-on?', choices: ['My cat sleeps all day, and she plays all night.', 'My cat sleeps all day; she plays all night.', 'My cat sleeps all day, but she plays all night.', 'My cat sleeps all day she plays all night.'], answer: 3, explain: 'Rule: a run-on joins two complete sentences with no punctuation. The others use a comma with "and" or "but," or a semicolon.' },
  { id: 'conv-049', skill: 'conventions', sub: 'run-ons and fragments', q: 'Which revision fixes the comma splice? "We went to the aquarium, we saw a shark."', choices: ['We went to the aquarium, we saw, a shark.', 'We went to the aquarium, and we saw a shark.', 'We went to the aquarium we saw a shark.', 'We went, to the aquarium we saw a shark.'], answer: 1, explain: 'Rule: a comma alone can\'t join two complete sentences (that\'s a comma splice). Add a joining word like "and" after the comma.' },
  { id: 'conv-050', skill: 'conventions', sub: 'run-ons and fragments', q: 'Which of these is a fragment?', choices: ['The girl with the purple skateboard.', 'The girl rode a purple skateboard.', 'She has a purple skateboard.', 'Look at that purple skateboard!'], answer: 0, explain: 'Rule: a fragment is missing a verb or a complete thought. "The girl with the purple skateboard" never says what the girl does.' },
  { id: 'conv-051', skill: 'conventions', sub: 'run-ons and fragments', q: 'Which revision fixes the run-on? "Practice starts at four don\'t be late."', choices: ['Practice starts at four, don\'t be late.', 'Practice starts, at four don\'t be late.', 'Practice starts at four, so don\'t be late.', 'Practice starts at four don\'t, be late.'], answer: 2, explain: 'Rule: join two complete thoughts with a comma plus a joining word like "so," or split them into two sentences.' },
  // conventions: subject-verb agreement
  { id: 'conv-052', skill: 'conventions', sub: 'subject-verb agreement', q: 'Choose the word that completes the sentence: "The players on the team ___ new jerseys."', choices: ['needs', 'needing', 'need', 'has needed'], answer: 2, explain: 'Rule: the verb agrees with the subject, "players," which is plural. Ignore "on the team": "The players need."' },
  { id: 'conv-053', skill: 'conventions', sub: 'subject-verb agreement', q: 'Choose the word that completes the sentence: "Neither my brother nor my sisters ___ broccoli."', choices: ['like', 'likes', 'liking', 'is liking'], answer: 0, explain: 'Rule: with "neither...nor," the verb agrees with the subject closer to it. "Sisters" is plural, so use "like."' },
  { id: 'conv-054', skill: 'conventions', sub: 'subject-verb agreement', q: 'Which sentence is written correctly?', choices: ['Each of the puppies have a blue collar.', 'Each of the puppies has a blue collar.', 'Each of the puppies having a blue collar.', 'Each of the puppies are having a blue collar.'], answer: 1, explain: 'Rule: "each" is singular, so it takes the singular verb "has," even when "puppies" comes after it.' },
  { id: 'conv-055', skill: 'conventions', sub: 'subject-verb agreement', q: 'Choose the word that completes the sentence: "My friends and I ___ to the skate park every Saturday."', choices: ['goes', 'going', 'has gone', 'go'], answer: 3, explain: 'Rule: two subjects joined by "and" are plural, so use the plural verb "go."' },
  { id: 'conv-056', skill: 'conventions', sub: 'subject-verb agreement', q: 'Choose the word that completes the sentence: "The box of crayons ___ on the shelf."', choices: ['are', 'were', 'be', 'is'], answer: 3, explain: 'Rule: the subject is "box," which is singular. Ignore "of crayons": "The box is on the shelf."' },
  { id: 'conv-057', skill: 'conventions', sub: 'subject-verb agreement', q: 'Choose the word that completes the sentence: "Everyone in the band ___ a solo this year."', choices: ['gets', 'get', 'are getting', 'have gotten'], answer: 0, explain: 'Rule: "everyone" is singular, so it takes the singular verb "gets."' },
  { id: 'conv-058', skill: 'conventions', sub: 'subject-verb agreement', q: 'Which sentence is written correctly?', choices: ['There is three cookies left in the jar.', 'There be three cookies left in the jar.', 'There are three cookies left in the jar.', 'There\'s three cookies left in the jar.'], answer: 2, explain: 'Rule: in a "there is / there are" sentence, the subject comes after the verb. "Cookies" is plural, so use "are."' },
  { id: 'conv-059', skill: 'conventions', sub: 'subject-verb agreement', q: 'Choose the word that completes the sentence: "Math and science ___ my favorite subjects."', choices: ['is', 'are', 'was', 'be'], answer: 1, explain: 'Rule: two subjects joined by "and" are plural, so use the plural verb "are."' },
  // conventions: homophones
  { id: 'conv-060', skill: 'conventions', sub: 'homophones', q: 'Choose the word that completes the sentence: "___ going to the dance competition on Saturday."', choices: ['Their', 'There', 'Theirs', 'They\'re'], answer: 3, explain: 'Rule: "they\'re" is short for "they are": "They are going to the dance competition."' },
  { id: 'conv-061', skill: 'conventions', sub: 'homophones', q: 'Choose the word that completes the sentence: "The dog wagged ___ tail."', choices: ['its', 'it\'s', 'its\'', 'it is'], answer: 0, explain: 'Rule: "its" (no apostrophe) shows ownership. "It\'s" always means "it is" or "it has." "Its\'" is never correct.' },
  { id: 'conv-062', skill: 'conventions', sub: 'homophones', q: 'Choose the word that completes the sentence: "We had ___ much homework to finish before practice."', choices: ['to', 'two', 'too', 'tow'], answer: 2, explain: 'Rule: "too" means "very" or "also." "To" shows direction, and "two" is the number 2.' },
  { id: 'conv-063', skill: 'conventions', sub: 'homophones', q: 'Choose the word that completes the sentence: "Our ___ read the announcements over the loudspeaker."', choices: ['principle', 'principal', 'principles', 'principle\'s'], answer: 1, explain: 'Rule: a "principal" is the head of a school (your principal is your pal). A "principle" is a rule or belief.' },
  { id: 'conv-064', skill: 'conventions', sub: 'homophones', q: 'Choose the word that completes the sentence: "The rainy weather will ___ our plans for the picnic."', choices: ['affect', 'effect', 'effects', 'affection'], answer: 0, explain: 'Rule: "affect" is usually a verb (an action). "Effect" is usually a noun (a result). Here we need the action word.' },
  { id: 'conv-065', skill: 'conventions', sub: 'homophones', q: 'Choose the word that completes the sentence: "The special ___ in the movie looked so real."', choices: ['affects', 'effects', 'affect', 'affected'], answer: 1, explain: 'Rule: "effect" is a noun that means a result. "Special effects" are the results that make movie scenes look real.' },
  { id: 'conv-066', skill: 'conventions', sub: 'homophones', q: 'Choose the word that completes the sentence: "I can\'t decide ___ to wear the red shirt or the blue one."', choices: ['weather', 'wether', 'whither', 'whether'], answer: 3, explain: 'Rule: "whether" introduces a choice. "Weather" means rain, sun, wind, and snow.' },
  { id: 'conv-067', skill: 'conventions', sub: 'homophones', q: 'Choose the word that completes the sentence: "We walked ___ the gym to get to the cafeteria."', choices: ['threw', 'thorough', 'through', 'though'], answer: 2, explain: 'Rule: "through" means in one side and out the other. "Threw" is the past tense of "throw."' },
  { id: 'conv-068', skill: 'conventions', sub: 'homophones', q: 'Which sentence is written correctly?', choices: ['Your going to love your new skateboard.', 'You\'re going to love your new skateboard.', 'You\'re going to love you\'re new skateboard.', 'Your going to love you\'re new skateboard.'], answer: 1, explain: 'Rule: "you\'re" means "you are." "Your" shows something belongs to you.' },
  // conventions: vague pronouns
  { id: 'conv-069', skill: 'conventions', sub: 'vague pronouns', q: 'Which sentence has a vague pronoun?', choices: ['Mia was upset when Ava talked to her.', 'Mia was upset, so she called her grandma.', 'Ava felt sad after Mia yelled at her.', 'When Mia talked to Ava, she was upset.'], answer: 3, explain: 'Rule: a pronoun is vague when it could point to more than one person. In the first sentence, "she" could mean Mia or Ava.' },
  { id: 'conv-070', skill: 'conventions', sub: 'vague pronouns', q: 'Which revision fixes the vague pronoun? "Jayden told Marcus that he won the contest."', choices: ['Jayden told Marcus, "You won the contest."', 'Jayden told Marcus that he really won the contest.', 'He told Marcus that he won the contest.', 'Jayden told him that he won the contest.'], answer: 0, explain: 'Rule: fix a vague pronoun by making it clear who is meant. "He" could be Jayden or Marcus, but "You" can only mean Marcus.' },
  { id: 'conv-071', skill: 'conventions', sub: 'vague pronouns', q: 'Which sentence has a vague pronoun?', choices: ['At the store, the clerk said the game was sold out.', 'The clerk said the new game was sold out.', 'At the store, they said the game was sold out.', 'The game was sold out, so we went home.'], answer: 2, explain: 'Rule: a pronoun is vague when it doesn\'t refer to any noun. Who are "they"? The sentence never says.' },
  { id: 'conv-072', skill: 'conventions', sub: 'vague pronouns', q: 'Which revision fixes the vague pronoun? "When the dog chased the cat, it ran up a tree."', choices: ['When the dog chased the cat, it quickly ran up a tree.', 'When it chased the cat, it ran up a tree.', 'The dog chased the cat, and it ran up a tree.', 'When the dog chased the cat, the cat ran up a tree.'], answer: 3, explain: 'Rule: replace a vague pronoun with the noun it means. "It" could be the dog or the cat, so name the cat.' },
  { id: 'conv-073', skill: 'conventions', sub: 'vague pronouns', q: 'Which sentence has a vague pronoun?', choices: ['Coach was mad because we forgot our gear.', 'Coach got mad when we forgot our gear.', 'We lost the game, missed the bus, and forgot our gear, and this made Coach mad.', 'Forgetting our gear made Coach mad.'], answer: 2, explain: 'Rule: "this" is vague when it could point to several things. Did losing, missing the bus, or forgetting the gear make Coach mad?' },
  { id: 'conv-074', skill: 'conventions', sub: 'vague pronouns', q: 'Which revision fixes the vague pronoun? "Sofia\'s mom said she could go to the concert."', choices: ['Sofia\'s mom said she could really go to the concert.', 'Sofia\'s mom said Sofia could go to the concert.', 'She said Sofia\'s mom could go to the concert.', 'Sofia\'s mom said that she could go.'], answer: 1, explain: 'Rule: "she" could be Sofia or her mom. Using the name "Sofia" makes it clear who is going.' },
  { id: 'conv-075', skill: 'conventions', sub: 'vague pronouns', q: 'Which sentence has a vague pronoun?', choices: ['In the article, it says that bees are disappearing.', 'The article says that bees are disappearing.', 'The author of the article says bees are disappearing.', 'According to the article, bees are disappearing.'], answer: 0, explain: 'Rule: "it" should stand for a noun. In "In the article, it says," the "it" doesn\'t stand for anything. Say "The article says."' },
  { id: 'conv-076', skill: 'conventions', sub: 'vague pronouns', q: 'Which revision fixes the vague pronoun? "Liam took the controller from his brother, and he started crying."', choices: ['Liam took the controller from his brother, and he started crying loudly.', 'Liam took the controller from his brother, and his brother started crying.', 'He took the controller from his brother, and he started crying.', 'Liam took it from his brother, and he started crying.'], answer: 1, explain: 'Rule: "he" could be Liam or his brother. Naming "his brother" makes it clear who cried.' },
  // conventions: intensive pronouns
  { id: 'conv-077', skill: 'conventions', sub: 'intensive pronouns', q: 'Choose the word that completes the sentence: "Maya ___ built the robot without any help."', choices: ['himself', 'itself', 'themselves', 'herself'], answer: 3, explain: 'Rule: an intensive pronoun adds emphasis and must match the noun. Maya is one girl, so use "herself."' },
  { id: 'conv-078', skill: 'conventions', sub: 'intensive pronouns', q: 'Which sentence uses an intensive pronoun correctly?', choices: ['The coach hisself painted the team banner.', 'The coach him painted the team banner.', 'The coach himself painted the team banner.', 'Myself painted the team banner.'], answer: 2, explain: 'Rule: intensive pronouns end in -self or -selves and come right after the noun they stress. "Hisself" is not a word, and "myself" can\'t be the subject.' },
  { id: 'conv-079', skill: 'conventions', sub: 'intensive pronouns', q: 'What is the job of the intensive pronoun in this sentence? "I myself saw the shooting star."', choices: ['to emphasize who saw it', 'to show the action goes back to the subject', 'to replace a noun that hasn\'t been named', 'to show who owns something'], answer: 0, explain: 'Rule: an intensive pronoun adds emphasis. You could remove "myself" and the sentence would still make sense.' },
  { id: 'conv-080', skill: 'conventions', sub: 'intensive pronouns', q: 'Which sentence uses an intensive pronoun (not a reflexive pronoun)?', choices: ['The students themselves planned the bake sale.', 'The students taught themselves to juggle.', 'The puppy hurt itself on the stairs.', 'I made myself a sandwich.'], answer: 0, explain: 'Rule: an intensive pronoun can be removed and the sentence still works. "The students planned the bake sale" still makes sense. In the others, the pronoun is needed, so they are reflexive.' },
  { id: 'conv-081', skill: 'conventions', sub: 'intensive pronouns', q: 'Choose the word that completes the sentence: "We ___ cleaned the entire garage."', choices: ['ourself', 'us', 'ourselves', 'themselves'], answer: 2, explain: 'Rule: the intensive pronoun must match the subject. "We" goes with "ourselves." "Ourself" is not standard English.' },
  { id: 'conv-082', skill: 'conventions', sub: 'intensive pronouns', q: 'Which sentence is written correctly?', choices: ['My brother and myself fixed the flat tire.', 'Me and my brother fixed the flat tire ourself.', 'My brother and I fixed the flat tire ourselfs.', 'My brother and I fixed the flat tire ourselves.'], answer: 3, explain: 'Rule: use "I" as a subject, not "myself." The -selves pronoun must match: "my brother and I" goes with "ourselves."' },
  { id: 'conv-083', skill: 'conventions', sub: 'intensive pronouns', q: 'How can you tell a pronoun is intensive?', choices: ['It always comes at the start of a sentence.', 'You can remove it and the sentence still makes sense.', 'It always ends in -ing.', 'It shows who owns something.'], answer: 1, explain: 'Rule: intensive pronouns (myself, herself, ourselves) only add emphasis, so the sentence still works without them.' },
  { id: 'conv-084', skill: 'conventions', sub: 'intensive pronouns', q: 'Choose the word that completes the sentence: "The tablet ___ wasn\'t broken; only the case was cracked."', choices: ['himself', 'themselves', 'itself', 'herself'], answer: 2, explain: 'Rule: the intensive pronoun must match its noun. A tablet is a thing, so use "itself."' },
  // conventions: capitalization
  { id: 'conv-085', skill: 'conventions', sub: 'capitalization', q: 'Which sentence is capitalized correctly?', choices: ['Last Summer we visited the grand canyon in Arizona.', 'Last summer we visited the Grand Canyon in Arizona.', 'last summer we visited the Grand Canyon in arizona.', 'Last summer we visited the Grand canyon in Arizona.'], answer: 1, explain: 'Rule: capitalize proper nouns, like the names of places (Grand Canyon, Arizona). Seasons like summer are not capitalized.' },
  { id: 'conv-086', skill: 'conventions', sub: 'capitalization', q: 'Which sentence is capitalized correctly?', choices: ['My favorite subject is Science, but I also like spanish.', 'My Favorite Subject is science, but I also like Spanish.', 'my favorite subject is science, but I also like Spanish.', 'My favorite subject is science, but I also like Spanish.'], answer: 3, explain: 'Rule: languages like Spanish are always capitalized. School subjects like science are not, unless they are a language.' },
  { id: 'conv-087', skill: 'conventions', sub: 'capitalization', q: 'Which sentence is capitalized correctly?', choices: ['On Monday, Aunt Rosa took us to the library.', 'On monday, aunt Rosa took us to the library.', 'On Monday, aunt Rosa took us to the Library.', 'On Monday, Aunt Rosa took us to the Library.'], answer: 0, explain: 'Rule: capitalize days of the week and a title used with a name (Aunt Rosa). A common noun like "library" stays lowercase.' },
  { id: 'conv-088', skill: 'conventions', sub: 'capitalization', q: 'Which sentence is capitalized correctly?', choices: ['Mansa Musa ruled the mali empire in west Africa.', 'mansa Musa ruled the Mali Empire in West Africa.', 'Mansa Musa ruled the Mali Empire in West Africa.', 'Mansa Musa ruled the Mali Empire in west africa.'], answer: 2, explain: 'Rule: capitalize names of people, empires, and regions: Mansa Musa, Mali Empire, West Africa.' },
  { id: 'conv-089', skill: 'conventions', sub: 'capitalization', q: 'Which sentence is capitalized correctly?', choices: ['"Can we get tacos tonight, Dad?" I asked.', '"Can we get tacos tonight, dad?" I asked.', '"can we get tacos tonight, Dad?" I asked.', '"Can we get Tacos tonight, Dad?" I asked.'], answer: 0, explain: 'Rule: capitalize "Dad" when you use it as a name. Capitalize the first word of a quotation. "Tacos" is a common noun.' },
  { id: 'conv-090', skill: 'conventions', sub: 'capitalization', q: 'Which sentence is capitalized correctly?', choices: ['Our family celebrates thanksgiving in November.', 'Our family celebrates Thanksgiving in november.', 'Our Family celebrates Thanksgiving in November.', 'Our family celebrates Thanksgiving in November.'], answer: 3, explain: 'Rule: capitalize holidays and months. Common nouns like "family" stay lowercase.' },
];
